public enum WireReason: String, Codable, Equatable, Sendable {
	case automatic = "Automatic"
	case approvalRequired = "ApprovalRequired"
	case reviewRequired = "ReviewRequired"
	case dependenciesOrResource = "DependenciesOrResource"
	case effectUncertain = "EffectUncertain"
	case reworking = "Reworking"
	case evidenceInvalidated = "EvidenceInvalidated"
	case completed = "Completed"
	case failed = "Failed"
	case cancelling = "Cancelling"
	case cancelled = "Cancelled"
	/// The runner stopped the run on changes in its worktree, and says which (ov-979).
	case worktreeChanged = "WorktreeChanged"
}

